import {libraryDocument} from '/archive.js';
import {preliminary,todayCanary,calendarRange,isRequested} from '/workflow.js';

import {GROUPS,FIELDS,SOURCES,DOC_TYPES,STATUSES,assess,completeness,parseCSV,validateProfile,makeMail,gmailUrl,normalize} from '/model.js';
const root=document.getElementById('app');
if(!window.__atlante){window.__atlante=true;start();}
let S={clients:[],opportunities:[],cases:[],documents:[],logs:[],sources:[],settings:{}},page=['cases','documents'].includes(location.hash.slice(1))?'clients':location.hash.slice(1)||'overview',q='',filters={},advanced=[],clientEdit=null,groupIndex=0,currentCase=null,currentOp=null,activeTab='documents',folderHandle=null,bulkSelect=false,selectedOpIds=new Set();
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8m-8 4h5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3 3-1 3 3 3-2h3l2-3-1-3 2-3-3-2-1-3h-4Z"/><circle cx="12" cy="12" r="3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m9 5 7 7-7 7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',up:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',leaf:'<path d="M20 3C12 2 3 5 4 14a6 6 0 0 0 6 6c9 1 11-9 10-17ZM4 20 15 9"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18m-10 0v3h2v-3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',filter:'<path d="M4 5h16l-6 7v7l-4 2v-9Z"/>',link:'<path d="M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2m3 6a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',edit:'<path d="m16 3 5 5L8 21H3v-5ZM13 6l5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>'};
const ic=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[n]||icons.file)+'</svg>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=s=>esc(s);const euro=n=>n==null?'Por verificar':new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const shortDate=d=>d?new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',timeZone:'Atlantic/Canary'}).format(new Date(d.length===10?d+'T12:00:00Z':d)):'Por verificar';
const fullDate=d=>d?new Intl.DateTimeFormat('es-ES',{dateStyle:'short',timeStyle:'short',timeZone:'Atlantic/Canary'}).format(new Date(d)):'Sin consulta';
const days=d=>{if(!d)return null;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Atlantic/Canary',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return Math.round((Date.parse(d+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000);};
const initials=s=>s.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const button=(label,action,icon='',primary=false,extra='')=>'<button class="btn '+(primary?'primary':'')+'" data-action="'+action+'" '+extra+'>'+(icon?ic(icon):'')+label+'</button>';
const badge=(label,color='')=>'<span class="badge '+color+'">'+esc(label)+'</span>';
const navs=[['overview','Resumen','grid'],['urgent','Urgencias','clock'],['opportunities','Oportunidades','spark'],['unclassified','Pendientes de clasificar','folder'],['clients','Clientes','users'],['sources','Fuentes oficiales','globe']];
async function api(path,data,method){const response=await fetch('/api/'+path,{method:method||(data?'POST':'GET'),headers:data instanceof FormData?{}:{'Content-Type':'application/json'},body:data instanceof FormData?data:data?JSON.stringify(data):undefined});const r=await response.json().catch(()=>({error:'El servidor no ha devuelto datos válidos.'}));if(!response.ok||r.error){const error=new Error(r.error||'Error de conexión');error.signIn=r.signIn;throw error;}return r;}
async function refresh(){S=await api('state');}
function toast(message){let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');document.body.appendChild(el);}el.textContent=message;el.style.display='block';clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.style.display='none',6000);}
function empty(title,text,cta=''){return '<div class="empty">'+ic('folder')+'<h3>'+title+'</h3><p>'+text+'</p>'+cta+'</div>';}
function client(id){return S.clients.find(c=>c.id===id);}function op(id){return S.opportunities.find(o=>o.id===id);}function doc(id){return S.documents.find(d=>d.id===id);}
function pending(c){return (c.requirements||[]).filter(r=>!r.docId||(doc(r.docId)?.expires&&doc(r.docId).expires<new Date().toISOString().slice(0,10))).length;}
function urgent(){const n=S.settings.window||15;return S.cases.filter(c=>!['Presentado','Concedido','Denegado','Archivado'].includes(c.status)&&!['No cumple','Descartado'].includes(c.communication)&&(pending(c)>0||!c.requirements.length)&&days(op(c.opId)?.deadline)!==null&&days(op(c.opId).deadline)<=n).sort((a,b)=>String(op(a.opId)?.deadline).localeCompare(String(op(b.opId)?.deadline)));}
function matches(o){if(isIgnored(o))return [];return S.clients.filter(c=>preliminary(c,o).status==='potential'&&!isDismissed(c.id,o.id));}

function head(title,description,actions=''){return '<div class="pagehead"><div><h1>'+title+'</h1><p>'+description+'</p></div><div class="row">'+actions+'</div></div>';}
function go(p){bulkSelect=false;selectedOpIds.clear();if(p==='cases'||p==='documents')p='clients';selectedClient=null;page=p;q='';filters={};advanced=[];location.hash=p;closeModal();render();window.scrollTo(0,0);}
function render(){
 if(!S.settings.agencyName){renderRegistration();return;}
 const title=[...navs,['sources','Fuentes oficiales'],['settings','Configuración']].find(n=>n[0]===page)?.[1]||'Resumen';
 root.innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><svg viewBox="0 0 36 36" aria-hidden="true"><path d="M3 28 15 5h6l12 23H23l-5-11-5 11Z" fill="currentColor" stroke="none"/><path d="M3 28h30" stroke="rgb(153,184,133)" stroke-width="3"/></svg>atlante<span style="font-size:13px;align-self:flex-start;margin-top:5px">®</span></div><div class="nav-label">GESTIÓN PARA ASESORÍAS</div><nav class="nav">'+navs.map(([p,t,i])=>'<button class="'+(page===p?'active':'')+'" data-action="nav" data-page="'+p+'">'+ic(i)+t+(p==='urgent'&&urgent().length?'<span class="count">'+urgent().length+'</span>':'')+'</button>').join('')+'</nav><div class="nav-bottom"><div class="sidebar-note">'+ic('shield')+'<div style="margin-top:7px">Cada decisión, con su fuente.<br><small>La revisión humana siempre cuenta.</small></div></div><nav class="nav">'+[['settings','Configuración','settings']].map(([p,t,i])=>'<button class="'+(page===p?'active':'')+'" data-action="nav" data-page="'+p+'">'+ic(i)+t+'</button>').join('')+'</nav></div></aside><section class="content"><header class="topbar"><button class="iconbtn mobile-menu" data-action="menu" aria-label="Abrir menú">'+ic('menu')+'</button><div class="crumb">'+esc(S.settings.agencyName||'Mi asesoría')+' <span>/ &nbsp;'+title+'</span></div><label class="searchbox">'+ic('search')+'<input type="search" id="global-search" placeholder="Buscar clientes u oportunidades…" aria-label="Buscar en el espacio"><span class="key">⌘ K</span></label><div class="top-right"><span class="today">'+new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'long',year:'numeric',timeZone:'Atlantic/Canary'}).format(new Date())+'</span><button class="iconbtn" data-action="nav" data-page="urgent" aria-label="Ver urgencias">'+ic('bell')+'</button><button type="button" class="avatar identity-link" data-action="identity" aria-label="Mi perfil">'+esc(S.currentUser?initials(S.currentUser.name):'AT')+'</button></div></header><main class="main" id="main-content"></main></section></div>';
 renderMain();
}
function renderMain(){const main=document.getElementById('main-content');main.innerHTML=({overview:overview,opportunities:opportunities,unclassified:unclassified,clients:clients,cases:cases,documents:documents,urgent:urgencies,sources:sources,settings:settings}[page]||overview)();main.innerHTML+='<div class="footer-line"><span>Atlante · Un espacio para avanzar con criterio.</span><span>Canarias · Atlantic/Canary</span></div>';if(S.clients.some(c=>c.demo))main.innerHTML+='<div class="demo-note">'+ic('info')+'Los clientes y las oportunidades marcados «Ejemplo» son ficticios. Las publicaciones reales se identifican por su fuente.</div>';}
function overview(){return head('Las ayudas de tus clientes, bajo control.','El espacio de trabajo del equipo de tu asesoría para gestionar subvenciones, ayudas y licitaciones.')+advisorIntro()+'<div class="stats">'+[['clients','Clientes',S.clients.length],['opportunities','Oportunidades',S.opportunities.filter(o=>matches(o).length).length],['unclassified','Pendientes de clasificar',unclassifiedOps().length],['urgent','Urgencias',urgent().length]].map(([p,t,n])=>'<button class="panel tablebtn" data-action="nav" data-page="'+p+'"><h3>'+t+'</h3><div class="stat-value">'+n+'</div></button>').join('')+'</div><div class="sectionhead"><h2>Próximas acciones</h2></div>'+caseTable(urgent().slice(0,5));}

function opCard(o){const m=matches(o);return '<article class="op-card"><div class="card-top"><span class="op-icon">'+ic(o.type==='Licitación'?'briefcase':o.tag==='Sostenibilidad'?'leaf':'spark')+'</span>'+badge(o.demo?'Ejemplo':o.verified?'Bases revisadas':'Por analizar',o.demo?'gray':o.verified?'':'blue')+'</div><div class="tagline">'+esc(o.type)+' · '+esc(o.tag||'Convocatoria')+'</div><h3>'+esc(o.title)+'</h3><p class="description">'+esc(o.summary)+'</p><div class="op-meta"><div><small>'+(o.type==='Licitación'?'Presupuesto':'Importe orientativo')+'</small><strong>'+euro(o.amount)+'</strong></div><div><small>Fin de plazo</small><span>'+shortDate(o.deadline)+'</span></div></div><div class="card-bottom"><div class="row" style="gap:7px"><span class="avatars">'+m.slice(0,3).map(c=>'<span>'+initials(c.profile.name)+'</span>').join('')+'</span><span class="muted">'+(m.length?m.length+' clientes potenciales':'Encaje por verificar')+'</span></div><button class="card-arrow" data-action="op" data-id="'+attr(o.id)+'" aria-label="Ver '+attr(o.title)+'">'+ic('arrow')+'</button></div></article>';}
function deadlineItem(c){const o=op(c.opId);return '<div class="deadline-item" data-action="case" data-id="'+attr(c.id)+'"><div class="days">'+(days(o?.deadline)<0?'Plazo vencido':days(o?.deadline)+' días para actuar')+' <span class="muted">· '+shortDate(o?.deadline)+'</span></div><h4>'+esc(client(c.clientId)?.profile.name)+'</h4><p>'+esc(o?.title)+'</p><div class="progress"><i style="width:'+((c.requirements.length-pending(c))/Math.max(1,c.requirements.length)*100)+'%"></i></div><p style="margin-top:8px">'+pending(c)+' documentos pendientes</p></div>';}
function opportunities(){const list=S.opportunities.filter(o=>matches(o).length&&normalize(o.title+' '+o.summary).includes(normalize(q))&&(!filters.type||o.type===filters.type));return head('Oportunidades','Primer filtro orientativo: cada anuncio tiene una señal de interés para algún cliente.',button('Revisar fuentes','scan','refresh',true))+'<div class="toolbar"><input data-search placeholder="Buscar oportunidades…" value="'+attr(q)+'">'+selectFilter('type',['Ayuda','Subvención','Licitación'],'Todos los tipos')+'<span class="countpill">'+list.length+' resultados</span></div><p class="help">El interés por actividad o proyecto no confirma elegibilidad. Abre una oportunidad para ver fuentes y criterios; la lectura automática de pliegos aún no está activada.</p>'+(list.length?'<div class="op-grid">'+list.map(o=>'<div>'+opCard(o)+'<p class="help">'+matches(o).map(c=>esc(c.profile.name)+': '+esc(preliminary(c,o).reasons.join('; '))).join('<br>')+'</p></div>').join('')+'</div>':empty('Sin coincidencias preliminares','Consulta Pendientes de clasificar o completa las fichas de tus clientes.'));}

function selectFilter(key,values,label){return '<select data-filter="'+key+'" aria-label="'+label+'"><option value="">'+label+'</option>'+values.map(v=>{const [value,text]=Array.isArray(v)?v:[v,v];return '<option value="'+attr(value)+'" '+(filters[key]===value?'selected':'')+'>'+esc(text)+'</option>';}).join('')+'</select>';}
function filterClients(){return S.clients.filter(c=>{const p=c.profile;if(!normalize(Object.values(p).join(' ')).includes(normalize(q)))return false;if(['sector','island','entity','municipality'].some(k=>filters[k]&&p[k]!==filters[k]))return false;return advanced.every(r=>{const v=p[r.field];if(r.op==='empty')return v===undefined||v==='';if(v===undefined||v==='')return false;return r.op==='eq'?normalize(v)===normalize(r.value):r.op==='contains'?normalize(v).includes(normalize(r.value)):r.op==='gte'?Number(v)>=Number(r.value):Number(v)<=Number(r.value);});}).sort((a,b)=>a.profile.name.localeCompare(b.profile.name,'es'));}
function clients(){if(selectedClient)return clientWorkspace();const list=filterClients();return head('Clientes de la asesoría','Fichas gestionadas por tu equipo.',button('Importar CSV','import','up')+button('Nuevo cliente','new-client','plus',true))+'<div class="toolbar"><input data-search placeholder="Buscar cliente…" value="'+attr(q)+'">'+selectFilter('sector',GROUPS[2][1].find(f=>f[0]==='sector')[3],'Todos los sectores')+button('Más filtros','advanced','filter')+'</div>'+(list.length?'<div class="panel client-list">'+list.map(c=>'<button class="client-folder" data-action="client" data-id="'+attr(c.id)+'">'+ic('folder')+'<span>'+esc(c.profile.name)+'</span>'+ic('chevron')+'</button>').join('')+'</div>':empty('Sin clientes','Añade o importa una ficha para comenzar.'));}

function clientTable(list){return '<div class="tablewrap"><table><thead><tr><th>Cliente</th><th>Sector</th><th>Ubicación</th><th>Plantilla</th><th>Ficha básica</th><th>Expedientes</th><th></th></tr></thead><tbody>'+list.map(c=>'<tr><td><button class="tablebtn row" data-action="client" data-id="'+attr(c.id)+'"><span class="mini-avatar">'+initials(c.profile.name)+'</span><span><span class="client-name">'+esc(c.profile.name)+'</span><span class="sub" style="display:block">'+esc(c.profile.entity||'Tipo pendiente')+(c.demo?' · Ejemplo':'')+'</span></span></button></td><td>'+esc(c.profile.sector||'Pendiente')+'</td><td>'+esc(c.profile.municipality||'Pendiente')+'<div class="sub">'+esc(c.profile.island||'')+'</div></td><td>'+(c.profile.employees??'—')+'</td><td><div class="row"><span>'+completeness(c)+'%</span><div class="progress" style="width:65px;margin:0"><i style="width:'+completeness(c)+'%"></i></div></div></td><td>'+S.cases.filter(x=>x.clientId===c.id).length+'</td><td><button class="card-arrow" data-action="client" data-id="'+attr(c.id)+'" aria-label="Abrir ficha">'+ic('arrow')+'</button></td></tr>').join('')+'</tbody></table></div>';}
function variablesCard(){return '<div class="panel" style="margin-top:23px"><div class="row between"><div><h3 style="margin-bottom:4px">Una ficha que crece contigo</h3><p class="help" style="margin:0">'+FIELDS.length+' variables en '+GROUPS.length+' grupos. Solo el nombre es obligatorio; el resto se completa según las convocatorias.</p></div>'+ic('users')+'</div><div class="row wrap" style="gap:7px;margin-top:17px">'+GROUPS.map(g=>badge(g[0],'outline')).join('')+'</div><p class="help" style="margin:14px 0 0">Los campos sensibles o específicos solo deben rellenarse cuando sean pertinentes y estén acreditados. El sistema no deduce condiciones personales.</p></div>';}
function cases(){const list=S.cases.filter(c=>normalize(client(c.clientId)?.profile.name+' '+op(c.opId)?.title).includes(normalize(q))&&(!filters.type||op(c.opId)?.type===filters.type)&&(!filters.status||c.status===filters.status));return head('Cada expediente, bajo control.','Documentación, comunicaciones y trazabilidad por cliente.',button('Abrir expediente','new-case','plus',true))+'<div class="toolbar"><input type="search" data-search placeholder="Buscar cliente o convocatoria…" value="'+attr(q)+'">'+selectFilter('type',['Ayuda','Subvención','Licitación'],'Todos los tipos')+selectFilter('status',STATUSES,'Todos los estados')+'</div>'+caseTable(list);}
function caseTable(list){if(!list.length)return empty('Sin expedientes','Abre uno desde una oportunidad y su cliente para generar la lista documental.');return '<div class="tablewrap"><table><thead><tr><th>Cliente / convocatoria</th><th>Estado</th><th>Documentación</th><th>Plazo</th><th></th></tr></thead><tbody>'+list.map(c=>'<tr><td><button class="tablebtn" data-action="case" data-id="'+attr(c.id)+'"><div class="client-name">'+esc(client(c.clientId)?.profile.name)+'</div><div class="sub">'+esc(op(c.opId)?.title)+'</div></button></td><td>'+badge(c.status,c.status==='Presentado'?'':'gray')+'</td><td>'+(c.requirements.length?(c.requirements.length-pending(c))+' / '+c.requirements.length:'Pendiente de analizar')+'<div class="progress"><i style="width:'+((c.requirements.length-pending(c))/Math.max(1,c.requirements.length)*100)+'%"></i></div></td><td>'+shortDate(op(c.opId)?.deadline)+'</td><td><button class="card-arrow" data-action="case" data-id="'+attr(c.id)+'" aria-label="Ver expediente">'+ic('arrow')+'</button></td></tr>').join('')+'</tbody></table></div>';}
function documents(){const list=S.documents.filter(d=>normalize(d.name+' '+d.type+' '+client(d.client_id)?.profile.name).includes(normalize(q))&&(!filters.client||d.client_id===filters.client));return head('El archivo de tus clientes.','Documentos guardados, fecha de subida y reutilización controlada.',button('Carpeta local','folder','folder')+button('Subir documento','vault-upload','up',true))+'<div class="toolbar"><input type="search" data-search placeholder="Buscar documento o cliente…" value="'+attr(q)+'">'+selectFilter('client',S.clients.map(c=>[c.id,c.profile.name]),'Todos los clientes')+'</div>'+(list.length?'<div class="tablewrap"><table><thead><tr><th>Documento</th><th>Cliente</th><th>Subido</th><th>Reutilización</th><th></th></tr></thead><tbody>'+list.map(d=>'<tr><td><strong>'+esc(d.type)+'</strong><div class="sub">'+esc(d.name)+' · '+(d.size/1024).toFixed(0)+' KB</div></td><td>'+esc(client(d.client_id)?.profile.name)+'</td><td>'+fullDate(d.created)+'<div class="sub">'+esc(d.actor)+(d.actorEmail?' · '+esc(d.actorEmail):'')+'</div></td><td>'+badge(d.approved?(d.expires&&d.expires<new Date().toISOString().slice(0,10)?'Caducado':'Reutilizable'):'Pendiente de revisión',d.approved?'':'gray')+'</td><td><div class="row"><a class="iconbtn" href="/api/documents/'+encodeURIComponent(d.id)+'" aria-label="Descargar documento">'+ic('down')+'</a><button class="iconbtn" data-action="review-doc" data-id="'+attr(d.id)+'" aria-label="Revisar documento">'+ic('check')+'</button></div></td></tr>').join('')+'</tbody></table></div>':empty('Un único archivo para cada cliente','Sube documentos permanentes aquí. Tras revisarlos y marcar su vigencia, podrán reutilizarse al abrir nuevos expedientes.',button('Subir documento','vault-upload','up',true)))+'<div class="note" style="margin-top:22px">'+ic('info')+'La reutilización vincula el documento del mismo cliente. No valida automáticamente su contenido. Comprueba su vigencia y si la convocatoria exige un documento actualizado.</div>';}
function urgencies(){const range=calendarRange(calendarAnchor,calendarView),list=S.cases.filter(c=>!['Presentado','Concedido','Denegado','Archivado'].includes(c.status)&&isRequested(c,decision(c.clientId,c.opId))&&(pending(c)>0||!c.requirements.length)),unknown=list.filter(c=>!op(c.opId)?.deadline),late=list.filter(c=>op(c.opId)?.deadline&&op(c.opId).deadline<todayCanary());return head('Urgencias','Calendario de solicitudes con documentación pendiente.')+'<div class="toolbar">'+[['month','Mes'],['fortnight','Dos semanas'],['week','Semana']].map(([v,t])=>button(t,'calendar-view','',calendarView===v,'data-view="'+v+'"')).join('')+button('Anterior','calendar-move','',false,'data-step="-1"')+button('Hoy','calendar-today')+button('Siguiente','calendar-move','',false,'data-step="1"')+'<strong>'+new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(calendarAnchor+'T12:00:00Z'))+'</strong></div><p class="help">Se muestra el cierre registrado de la convocatoria, no un plazo documental individual. Vista seleccionada: '+shortDate(range[0])+' – '+shortDate(range.at(-1))+'.</p><div class="calendar-scroll"><div class="calendar">'+['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>'<div class="calendar-label">'+d+'</div>').join('')+range.map(day=>'<section class="calendar-day '+(day===todayCanary()?'calendar-today':'')+'"><strong>'+Number(day.slice(-2))+'</strong>'+list.filter(c=>op(c.opId)?.deadline===day).map(c=>'<button class="calendar-event" data-action="case" data-id="'+attr(c.id)+'"><strong>'+esc(client(c.clientId)?.profile.name)+'</strong><span>'+esc(op(c.opId)?.title)+'</span><small>'+(days(day)<0?'Vencido':days(day)===0?'Vence hoy':'Quedan '+days(day)+' días')+' · '+(c.requirements.length?pending(c)+' documentos pendientes':'Documentación por analizar')+'</small></button>').join('')+'</section>').join('')+'</div></div>'+(late.length?'<h3 style="margin-top:24px">Vencidos pendientes de resolver</h3>'+caseTable(late):'')+(unknown.length?'<h3 style="margin-top:24px">Sin plazo verificado</h3>'+caseTable(unknown):'');}

function sources(){const explanations={bdns:'Se consultan hasta 100 anuncios recientes y se seleccionan hasta 65 candidatos territoriales. No se recorre todo el histórico.',placsp:'Se lee la primera página de un canal Atom y hasta 40 candidatos. Faltan paginación y otros canales.',boc:'Se comprueba la portada, pero aún no se importan sus anuncios ni PDF.',bopsct:'La entrada anterior devolvía una página sin contenido suficiente. Ahora se consulta directamente el sumario; todavía no se importan sus anuncios.',boplp:'La entrada anterior devolvía una página sin contenido suficiente. Ahora se consulta directamente el sumario; todavía no se importan sus anuncios.'};return head('Información con origen.','Recogida de anuncios y análisis de bases son pasos distintos.',button('Añadir fuente','new-source','plus')+button('Consultar ahora','scan','refresh',true))+'<div class="note blue">'+ic('info')+'Cobertura parcial significa que el lector no recorre toda la fuente. Conectar una IA no resuelve por sí solo esos límites. Los resúmenes de bases requieren un análisis documental adicional.</div>'+SOURCES.map(src=>{const status=S.sources.find(x=>x.sourceId===src.id);return '<div class="source-card"><div class="source-icon">'+ic('globe')+'</div><div class="spacer"><div class="row between"><h3>'+esc(src.name)+'</h3>'+badge(!status?'Sin consultar':status.status==='error'?'Consulta fallida':'Cobertura parcial','gray')+'</div><p>'+esc(explanations[src.id])+'</p><details><summary>Última consulta</summary><p class="help">'+esc(status?.message||'No realizada')+'</p><small>'+fullDate(status?.checked)+'</small></details><a href="'+attr(src.url)+'" target="_blank" rel="noopener noreferrer" class="btn ghost">Abrir fuente</a></div></div>';}).join('')+(S.customSources||[]).map(src=>'<div class="source-card"><div class="spacer"><div class="row between"><h3>'+esc(src.name)+'</h3>'+badge('Consulta manual','gray')+'</div><p class="help">Fuente registrada. Su lector automático todavía no está configurado; «Consultar ahora» no la procesa.</p><p>'+esc(src.notes)+'</p><a class="btn" href="'+attr(src.url)+'" target="_blank" rel="noopener noreferrer">Abrir fuente</a></div></div>').join('');}

function settings(){return '<section class="panel"><h3>Atlante en tu ordenador y móvil</h3><p>Instálala como aplicación. Necesita conexión para trabajar con tus datos.</p><button class="btn" data-install-atlante>Instalar Atlante</button></section>'+ head('Tu asesoría y tu cuenta.','Datos de tu asesoría y perfil de tu cuenta personal.')+identityForm()+personalForm()+teamPanel()+'<div class="split"><div><form id="settings-form" class="panel settings-card"><h3>Revisión diaria</h3><p class="help">Se consultan fuentes solo cuando hay clientes. El cruce usa la ficha actual de cada cliente.</p><div class="formgrid"><div class="field"><label>Hora deseada de disponibilidad</label><input type="time" name="readyTime" required value="'+attr(S.settings.readyTime||'08:00')+'"></div><div class="field"><label>Ventana de urgencias (días)</label><input type="number" min="1" max="60" name="window" value="'+(S.settings.window||15)+'"></div><div class="field wide"><label>Ámbito de revisión</label><input name="scope" value="'+attr(S.settings.scope||'Canarias y convocatorias nacionales')+'"></div></div><p class="help">Zona horaria: Atlantic/Canary. La hora es un objetivo de disponibilidad, sujeto a la publicación de las fuentes y la duración de la revisión.</p><div class="note blue">'+ic('clock')+'Estado de automatización: '+esc(S.settings.scheduleStatus||'Pendiente de activación')+'. Cambiar aquí la hora guarda tu preferencia. Para cambiar la ejecución en segundo plano, solicita desde este chat «aplica el horario guardado en Atlante».</div><button class="btn primary">Guardar preferencias</button></form><div class="panel"><h3>Tu base de clientes</h3><p class="help">'+FIELDS.length+' variables. Descarga la plantilla y rellena solo los datos acreditados. Los vacíos se conservan como desconocidos.</p>'+button('Descargar plantilla CSV','template','down')+' <a class=\"btn\" href=\"/50-clientes-ficticios.csv\" download>Descargar 50 clientes ficticios</a></div></div><div><div class="panel settings-card"><h3>Archivo local</h3><p class="help">Elige una carpeta para guardar copias de los documentos que subas desde este navegador. La primera vez debes conceder acceso. En Chrome o Edge compatibles.</p><div id="folder-status" class="note">'+ic('folder')+(folderHandle?'Carpeta seleccionada: '+esc(folderHandle.name):'Carpeta local sin seleccionar en esta sesión.')+'</div>'+button('Elegir carpeta','folder','folder')+' '+button('Copiar archivo completo','sync-folder','down')+'<p class="help" style="margin-top:15px">Estructura: Ayudas, Licitaciones o Subvenciones → cliente → convocatoria y mes. Los documentos permanentes van a Documentos del cliente. Las copias existentes se actualizan al solicitar la sincronización.</p></div><div class="panel settings-card"><h3>Copias de seguridad</h3><p class="help">Exporta fichas, criterios e historial en JSON. Para guardar también los archivos, utiliza «Copiar archivo completo». El JSON no contiene los documentos binarios.</p>'+button('Exportar datos JSON','backup','down')+'</div><div class="panel"><h3>Google Drive · siguiente fase</h3><p class="help">Drive permite crear carpetas y subir archivos con autorización OAuth. Esta versión no está conectada a tu Drive. Puedes elegir una carpeta de Drive para escritorio sincronizada como destino local.</p><a class="btn ghost" href="https://developers.google.com/workspace/drive/api/guides/manage-uploads" target="_blank" rel="noopener noreferrer">Documentación oficial '+ic('link')+'</a></div></div></div>';}

let modalReturnFocus=null;
function showModal(title,html,footer='',size=''){closeModal();modalReturnFocus=document.activeElement;const div=document.createElement('div');div.id='modal';div.className='modal-backdrop';div.innerHTML='<section class="modal '+size+'" role="dialog" aria-modal="true" aria-label="'+attr(title)+'"><header class="modal-head"><h2>'+title+'</h2><button class="iconbtn" data-action="close" aria-label="Cerrar">'+ic('close')+'</button></header><div class="modal-body">'+html+'</div>'+(footer?'<footer class="modal-foot">'+footer+'</footer>':'')+'</section>';document.body.appendChild(div);setTimeout(()=>div.querySelector('button,input,select,textarea')?.focus(),50);}
function closeModal(){document.getElementById('modal')?.remove();modalReturnFocus?.focus?.();}
function editor(c){clientEdit=c?structuredClone(c):{profile:{active:'Sí'}};groupIndex=0;showModal(c?esc(c.profile.name):'Nuevo cliente','<div id="client-editor-content"></div>',(c?button('Ver expedientes','client-cases','folder',false,'data-id="'+attr(c.id)+'"')+'<span class="spacer"></span>':'')+button('Cancelar','close')+button('Guardar ficha','save-client','check',true),'wide');renderEditor();}
function renderEditor(){const p=clientEdit.profile;document.getElementById('client-editor-content').innerHTML=(clientEdit.demo?'<div class="note">'+ic('info')+'Cliente ficticio. Puedes editar la ficha y probar la gestión documental.</div>':'')+'<p class="help">Solo el nombre es obligatorio. Vacío significa desconocido. No uses cero o «No» para datos que no tienes.</p><div class="client-editor"><nav class="form-nav">'+GROUPS.map(([name,fs],i)=>'<button class="'+(i===groupIndex?'active':'')+'" data-action="group" data-index="'+i+'">'+esc(name)+' <small>'+fs.filter(f=>p[f[0]]!==undefined&&p[f[0]]!=='').length+'/'+fs.length+'</small></button>').join('')+'</nav><form id="client-form"><h3>'+GROUPS[groupIndex][0]+'</h3><div class="formgrid">'+GROUPS[groupIndex][1].map(([key,label,type,options])=>'<div class="field '+(type==='textarea'?'wide':'')+'"><label for="p-'+key+'">'+esc(label)+(key==='name'?' *':'')+'</label>'+(type==='select'?'<select id="p-'+key+'" data-profile="'+key+'"><option value="">Sin dato / pendiente</option>'+options.map(v=>'<option '+(p[key]===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select>':type==='textarea'?'<textarea id="p-'+key+'" data-profile="'+key+'">'+esc(p[key]||'')+'</textarea>':'<input id="p-'+key+'" data-profile="'+key+'" type="'+type+'" '+(type==='number'?'step="any"':'')+' value="'+attr(p[key]??'')+'" '+(key==='name'?'required':'')+'>')+'</div>').join('')+'</div><div class="row between" style="margin-top:23px">'+(groupIndex>0?button('Anterior','group','',false,'data-index="'+(groupIndex-1)+'"'):'<span></span>')+(groupIndex<GROUPS.length-1?button('Siguiente grupo','group','arrow',false,'data-index="'+(groupIndex+1)+'"'):'')+'</div></form></div>';}
function opDetail(id){const o=op(id);if(!o)return;currentOp=o;const ranked=S.clients.map(c=>({c,a:assess(c,o)})).sort((a,b)=>b.a.score-a.a.score);
showModal(esc(o.title),'<div class="row wrap">'+badge(o.type)+badge(o.demo?'Ejemplo ficticio':o.verified?'Bases revisadas':'Análisis pendiente','blue')+badge('Versión '+o.version,'outline')+'</div><p class="help" style="margin-top:12px">'+esc(o.organism)+'</p><p class="detail-summary">'+esc(o.summary)+'</p>'+(!o.verified?'<div class="note blue">'+ic('info')+(o.demo?'Esta oportunidad es ficticia y permite probar el flujo completo.':'Publicación detectada. Las bases no están completamente verificadas; no hay confirmación de elegibilidad.')+'</div>':'')+'<div class="detail-stats"><div class="detail-stat"><small>Importe orientativo</small><strong>'+euro(o.amount)+'</strong></div><div class="detail-stat"><small>Fin de plazo</small><strong>'+shortDate(o.deadline)+'</strong></div><div class="detail-stat"><small>Clientes con posible encaje</small><strong>'+matches(o).length+' / '+S.clients.length+'</strong></div></div><div class="split"><div><h3>Requisitos de preselección</h3><ul class="checklist">'+(o.rules?.length?o.rules.map(r=>'<li>'+ic('check')+'<span>'+esc(r.label||FIELDS.find(f=>f.key===r.field)?.label)+'<div class="sub">'+esc(r.op==='in'?r.value.join(', '):r.value)+'</div></span></li>').join(''):'<li>Criterios pendientes de contraste con las bases.</li>')+'</ul></div><div><h3>Documentación prevista</h3><ul class="checklist">'+(o.requirements?.length?o.requirements.map(r=>'<li>'+ic('file')+esc(typeof r==='string'?r:r.type)+'</li>').join(''):'<li>Lista documental pendiente de revisar.</li>')+'</ul></div></div><div class="divider"></div><h3>Fuentes y apartados</h3>'+(o.sources?.length?o.sources.map(s=>'<a class="list-source" style="display:block" href="'+attr(s.url)+'" target="_blank" rel="noopener noreferrer">'+ic('link')+' '+esc(s.name||'Documento oficial')+'<small>'+esc(s.section||'Apartado pendiente de identificar')+'</small></a>').join(''):'<p class="help">Ejemplo de prueba. No corresponde a una convocatoria oficial.</p>')+'<div class="divider"></div><h3>Qué clientes conviene revisar</h3><p class="help">Solo se contrastan los criterios registrados. Comprueba todas las bases antes de confirmar la solicitud.</p><div class="tablewrap"><table><thead><tr><th>Cliente</th><th>Evaluación y motivos</th><th></th></tr></thead><tbody>'+ranked.map(({c,a})=>'<tr><td>'+esc(c.profile.name)+'</td><td>'+badge(a.status,a.status==='Posible encaje'?'':a.status==='No cumple'?'gray':'blue')+'<div class="reasons">'+esc(a.no.length?'No cumple: '+a.no.join('; '):a.unknown.length?'Pendiente: '+a.unknown.join('; '):a.yes.length?a.yes.join('; '):'Sin criterios verificados.')+'</div></td><td>'+button('El cliente quiere solicitarla','open-case','plus',false,'data-client="'+attr(c.id)+'" data-op="'+attr(o.id)+'"')+'</td></tr>').join('')+'</tbody></table></div>',button('Editar análisis','edit-op','edit',false,'data-id="'+attr(o.id)+'"')+button('Cerrar','close'),'wide');}
function caseDetail(id,tab='documents'){currentCase=S.cases.find(c=>c.id===id);if(!currentCase)return;activeTab=tab;const c=currentCase,p=client(c.clientId),o=op(c.opId);showModal(esc(p?.profile.name),'<div class="row wrap">'+badge(o?.type||'Expediente')+badge(c.status,'gray')+(o?.demo?badge('Ejemplo ficticio','outline'):'')+'</div><h2 class="case-title">'+esc(o?.title)+'</h2><p class="help">Abierto el '+fullDate(c.created)+' · '+esc(o?.type)+' / '+esc(p?.profile.name)+' / '+esc(o?.title)+' '+c.created.slice(0,7)+'</p><div class="tabs">'+[['documents','Documentación','file'],['mail','Comunicación','mail'],['timeline','Seguimiento','clock']].map(([t,l,i])=>'<button class="'+(t===tab?'active':'')+'" data-action="case-tab" data-tab="'+t+'">'+ic(i)+' '+l+'</button>').join('')+'</div><div id="case-content"></div>',button('Ver convocatoria','op','link',false,'data-id="'+attr(o.id)+'"')+'<span class="spacer"></span><span class="help">Fin de plazo: '+shortDate(o?.deadline)+'</span>','wide');renderCaseTab();if(tab==='timeline')loadCaseHistory(id);}
function renderCaseTab(){const c=currentCase,p=client(c.clientId),o=op(c.opId),el=document.getElementById('case-content');if(activeTab==='documents'){el.innerHTML='<div class="row between wrap" style="margin-bottom:21px"><div><h3 style="margin-bottom:5px">'+(c.requirements.length?(c.requirements.length-pending(c))+' de '+c.requirements.length+' documentos subidos':'Documentación pendiente de analizar')+'</h3><p class="help" style="margin:0">Arrastra un archivo al requisito o pulsa «Subir».</p></div><div class="field"><label for="case-status">Estado del expediente</label><select id="case-status">'+STATUSES.map(v=>'<option '+(c.status===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div></div>'+c.requirements.map(r=>{const d=doc(r.docId);return '<div class="document-row" data-drop="'+attr(r.id)+'"><div class="doc-icon">'+ic(d?'check':'file')+'</div><div class="docinfo"><h4>'+esc(r.type)+'</h4><p>'+(d?esc(d.name)+' · Subido '+fullDate(d.created)+' por '+esc(d.actor):'Pendiente de recibir · máximo 20 MB')+'</p>'+(r.reused?'<div style="margin-top:6px">'+badge('Reutilizado del archivo del cliente')+'</div>':'')+'</div>'+(d?'<a class="iconbtn" href="/api/documents/'+encodeURIComponent(d.id)+'" aria-label="Descargar">'+ic('down')+'</a>':'')+'<button class="btn" data-action="upload-req" data-id="'+attr(r.id)+'">'+ic('up')+(d?'Sustituir':'Subir')+'</button></div>';}).join('')+(!c.requirements.length?empty('Lista de documentos pendiente','Revisa las bases y añade los documentos necesarios.'):'')+'<div class="row wrap" style="margin:16px 0">'+button('Añadir requisito','add-req','plus')+button('Actualizar desde las bases','sync-req','refresh')+button('Buscar en archivo del cliente','reuse-docs','folder')+'</div><div class="field"><label>Notas internas</label><textarea id="case-notes">'+esc(c.notes||'')+'</textarea></div><div style="margin-top:12px">'+button('Guardar notas','save-notes','check')+'</div>';}else if(activeTab==='mail'){const blocked=['Comunicado','Descartado','No cumple'].includes(c.communication),m=c.mail||(blocked?{to:p.profile.email||'',subject:'',body:'Comunicación cerrada. No se genera un nuevo borrador.'}:makeMail(p,o,c,{...S.settings,responsibleName:S.currentUser?.name||S.actor,mailSignature:S.currentUser?.signature||'',contactEmail:S.currentUser?.email||S.settings.contactEmail}));el.innerHTML='<div class="row between wrap" style="margin-bottom:15px">'+badge(c.communication,blocked?'gray':'')+'<div class="field"><label>Estado de comunicación</label><select id="communication-status">'+['Pendiente','Borrador revisado','Abierto en Gmail','Comunicado','Descartado','No cumple'].map(v=>'<option '+(c.communication===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div></div>'+(blocked?'<div class="note blue">'+ic('shield')+'Comunicación bloqueada para evitar duplicados. Cambia el estado deliberadamente si necesitas retomarla.</div>':'')+(c.communicationVersion!==o.version?'<div class="note blue">'+ic('info')+'Hay una nueva versión de la convocatoria. Revisa los cambios antes de adaptar el correo.</div>':'')+'<div class="mail"><div class="mail-top">'+ic('mail')+'Borrador para revisión · no se envía automáticamente</div><label>Para <input id="mail-to" type="email" value="'+attr(m.to)+'"></label><label>Asunto <input id="mail-subject" value="'+attr(m.subject)+'"></label><textarea id="mail-body">'+esc(m.body)+'</textarea><div class="mail-footer">'+button('Guardar borrador','save-mail','check')+button('Abrir en Gmail','gmail','arrow',true,blocked?'disabled':'')+'</div></div><p class="help" style="margin-top:13px">Gmail se abre con destinatario, asunto y texto en tu sesión iniciada. Marca «Comunicado» después de enviarlo: Atlante no lee el buzón ni verifica el envío.</p>';}else el.innerHTML='<div class="timeline">'+S.logs.filter(l=>l.caseId===c.id).map(l=>'<div class="timeline-item"><strong>'+esc(l.action)+'</strong><div style="margin-top:4px">'+esc(l.detail)+'</div><small>'+fullDate(l.at)+' · '+esc(l.actor)+(l.actorEmail?' · '+esc(l.actorEmail):'')+(!l.actorId&&l.actorKind!=='service'?' · Registro anterior sin identidad individual':'')+'</small></div>').join('')+'</div>';}

function newCaseDialog(presetClient){showModal('Abrir un expediente','<p class="help">Los documentos revisados y vigentes del cliente se vincularán automáticamente.</p><form id="new-case-form"><div class="field"><label>Cliente</label><select name="clientId" required>'+S.clients.map(c=>'<option value="'+attr(c.id)+'" '+(c.id===presetClient?'selected':'')+'>'+esc(c.profile.name)+'</option>').join('')+'</select></div><div class="field" style="margin-top:17px"><label>Convocatoria</label><select name="opId" required>'+S.opportunities.map(o=>'<option value="'+attr(o.id)+'">'+esc(o.title)+(o.demo?' · Ejemplo':'')+'</option>').join('')+'</select></div><button class="btn primary" style="margin-top:20px">Abrir expediente</button></form>','','small');}
let imported=[];
function importDialog(){showModal('Importar tu cartera de clientes','<div class="note">'+ic('info')+'Exporta tu Excel como CSV UTF-8. Admite comas o punto y coma. Valida el archivo completo antes de guardar; no sobrescribe clientes.</div><div class="upload-area">'+ic('up')+'<h3 style="margin-top:12px">Tu cartera, en un solo archivo</h3><p>Hasta 500 clientes por importación · CSV UTF-8</p><input type="file" id="csv-file" accept=".csv,text/csv"></div><div class="row wrap">'+button('Plantilla de clientes','template','down')+button('Diccionario de variables','dictionary','file')+'</div><p class="help" style="margin-top:15px">Admite claves técnicas y etiquetas del diccionario. Fechas: AAAA-MM-DD. Vacío significa desconocido.</p><div id="import-preview"></div>',button('Cancelar','close')+button('Importar clientes','confirm-import','check',true,'disabled'),'small');}
function advancedDialog(){showModal('Filtros de la cartera','<p class="help">Combina variables. Se deben cumplir todas las condiciones. Un dato vacío no pasa el filtro, salvo que elijas «Sin dato».</p><div id="advanced-rows"></div>'+button('Añadir condición','add-filter','plus'),button('Limpiar','clear-filters')+button('Aplicar filtros','apply-filters','filter',true),'small');drawFilters();}
function drawFilters(){document.getElementById('advanced-rows').innerHTML=advanced.map((r,i)=>'<div class="filterrow"><select data-af-field="'+i+'">'+FIELDS.map(f=>'<option value="'+f.key+'" '+(f.key===r.field?'selected':'')+'>'+esc(f.label)+'</option>').join('')+'</select><select data-af-op="'+i+'">'+[['eq','Igual a'],['contains','Contiene'],['gte','Al menos'],['lte','Como máximo'],['empty','Sin dato']].map(([v,l])=>'<option value="'+v+'" '+(r.op===v?'selected':'')+'>'+l+'</option>').join('')+'</select><input data-af-value="'+i+'" value="'+attr(r.value||'')+'" placeholder="Valor" '+(r.op==='empty'?'disabled':'')+'><button class="iconbtn" data-action="remove-filter" data-index="'+i+'" aria-label="Quitar condición">'+ic('close')+'</button></div>').join('');}
function uploadDialog(clientId,caseId='',reqId='',type=''){showModal('Subir documento','<p class="help">El archivo se asociará al cliente y al requisito. Máximo 20 MB.</p><form id="upload-form"><div class="formgrid"><div class="field"><label>Cliente</label><select name="clientId" '+(clientId?'disabled':'')+'>'+S.clients.map(c=>'<option value="'+attr(c.id)+'" '+(c.id===clientId?'selected':'')+'>'+esc(c.profile.name)+'</option>').join('')+'</select></div><div class="field"><label>Tipo de documento</label><input name="type" list="doc-types" required value="'+attr(type||'Otro documento')+'"><datalist id="doc-types">'+DOC_TYPES.map(t=>'<option>'+t+'</option>').join('')+'</datalist></div><div class="field"><label>Caducidad, si corresponde</label><input type="date" name="expires"></div><div class="field"><label>Destino documental</label><select name="scope"><option value="library" '+(!caseId?'selected':'')+'>Documentos del cliente</option><option value="case" '+(caseId?'selected':'')+'>Solo para este trámite</option></select></div><div class="field"><label>Ejercicio (cuentas anuales)</label><input name="year" type="number" min="2000" max="2099" placeholder="2025"></div><div class="field"><label>Archivo</label><input type="file" name="file" required></div></div><input type="hidden" name="fixedClient" value="'+attr(clientId)+'"><input type="hidden" name="caseId" value="'+attr(caseId)+'"><input type="hidden" name="reqId" value="'+attr(reqId)+'"><button class="btn primary" style="margin-top:22px">Subir y asociar</button></form>','','small');}
function docReview(id){const d=doc(id);showModal('Revisar documento','<h3>'+esc(d.type)+'</h3><p class="help">'+esc(d.name)+' · '+esc(client(d.client_id)?.profile.name)+'</p><form id="doc-review-form"><input type="hidden" name="id" value="'+attr(id)+'"><div class="field"><label>Destino documental</label><select name="scope"><option value="library" '+(libraryDocument(d)?'selected':'')+'>Documentos del cliente</option><option value="case" '+(!libraryDocument(d)?'selected':'')+'>Solo para este trámite</option></select></div><div class="field"><label>Ejercicio (cuentas anuales)</label><input name="year" type="number" min="2000" max="2099" value="'+attr(d.year||'')+'"></div><label class="toggle"><input type="checkbox" name="approved" '+(d.approved?'checked':'')+'>He revisado el contenido y es reutilizable para este cliente</label><div class="field" style="margin-top:20px"><label>Fecha de caducidad</label><input type="date" name="expires" value="'+attr(d.expires||'')+'"></div><p class="help">La ausencia de fecha no acredita vigencia indefinida. Para reutilizar cuentas, indica el ejercicio aquí y en el requisito, por ejemplo «Cuentas anuales 2025». No marques como reutilizable una memoria específica de una ayuda.</p><button class="btn primary">Guardar revisión</button></form>','','small');}
let opEditing=null;
function opEditor(id){opEditing=id?structuredClone(op(id)):{title:'',type:'Subvención',summary:'',rules:[],requirements:[],sources:[],verified:false};const o=opEditing;showModal(id?'Editar análisis':'Nueva convocatoria','<form id="op-form"><div class="formgrid"><div class="field wide"><label>Título</label><input name="title" required value="'+attr(o.title)+'"></div><div class="field"><label>Tipo</label><select name="type">'+['Ayuda','Subvención','Licitación'].map(t=>'<option '+(o.type===t?'selected':'')+'>'+t+'</option>').join('')+'</select></div><div class="field"><label>Organismo</label><input name="organism" value="'+attr(o.organism||'')+'"></div><div class="field"><label>Fin de plazo (vacío si no está verificado)</label><input type="date" name="deadline" value="'+attr(o.deadline||'')+'"></div><div class="field"><label>Importe orientativo (€)</label><input name="amount" type="number" min="0" value="'+attr(o.amount??'')+'"></div><div class="field wide"><label>Resumen contrastado con las bases</label><textarea name="summary" style="min-height:110px">'+esc(o.summary||'')+'</textarea></div><div class="field wide"><label>Documentación exigida (una por línea)</label><textarea name="requirements">'+esc((o.requirements||[]).map(r=>typeof r==='string'?r:r.type).join('\n'))+'</textarea></div><div class="field wide"><label>Fuentes: nombre | URL HTTPS | apartado exacto (una por línea)</label><textarea name="sources">'+esc((o.sources||[]).map(s=>[s.name||'Fuente',s.url,s.section||''].join(' | ')).join('\n'))+'</textarea></div></div><h3 style="margin-top:24px">Criterios verificables de preselección</h3><p class="help">Registra solo condiciones explícitas de las bases. Se contrastan todas; no sustituyen la revisión completa.</p><div id="rule-rows"></div>'+button('Añadir criterio','add-rule','plus')+'<div style="margin:24px 0"><label class="toggle"><input type="checkbox" name="verified" '+(o.verified?'checked':'')+'>He leído y contrastado las bases completas y los plazos</label></div><button type="submit" class="btn primary">Guardar análisis y versión</button></form>','','wide');drawRules();}
function drawRules(){document.getElementById('rule-rows').innerHTML=opEditing.rules.map((r,i)=>'<div class="rules-row"><select data-rule-field="'+i+'">'+FIELDS.map(f=>'<option value="'+f.key+'" '+(f.key===r.field?'selected':'')+'>'+esc(f.label)+'</option>').join('')+'</select><select data-rule-op="'+i+'">'+[['eq','Igual'],['contains','Contiene'],['gte','Al menos'],['lte','Como máximo'],['in','Una de (con |)']].map(([v,l])=>'<option value="'+v+'" '+(r.op===v?'selected':'')+'>'+l+'</option>').join('')+'</select><input data-rule-value="'+i+'" value="'+attr(Array.isArray(r.value)?r.value.join('|'):r.value??'')+'" placeholder="Valor"><button class="iconbtn" data-action="remove-rule" data-index="'+i+'" aria-label="Quitar criterio">'+ic('close')+'</button></div>').join('');}
function mailValues(){return {to:document.getElementById('mail-to').value.trim(),subject:document.getElementById('mail-subject').value,body:document.getElementById('mail-body').value};}
async function updateCase(data,tab=activeTab){const c=await api('cases/update',{id:currentCase.id,...data});await refresh();currentCase=c;caseDetail(c.id,tab);renderMain();return c;}
async function openApplication(clientId,opId){const c=await api('cases',{clientId,opId});await refresh();renderMain();caseDetail(c.id);if(folderHandle){try{await mirrorCase(S.cases.find(x=>x.id===c.id));}catch(e){toast('Solicitud creada; copia local pendiente: '+e.message);}}}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
const csvCell=s=>'"'+String(s??'').replace(/"/g,'""')+'"';
function downloadTemplate(){download('Atlante-plantilla-clientes.csv','\uFEFF'+FIELDS.map(f=>csvCell(f.key)).join(';')+'\r\n'+FIELDS.map(f=>csvCell(f.key==='name'?'Nombre de tu cliente':'')).join(';')+'\r\n','text/csv;charset=utf-8');}
function dictionary(){download('Atlante-diccionario-variables.csv','\uFEFF"Grupo";"Clave";"Variable";"Tipo";"Valores permitidos"\r\n'+FIELDS.map(f=>[f.group,f.key,f.label,f.type,Array.isArray(f.options)?f.options.join(' | '):f.key==='name'?'Obligatorio':'Vacío = pendiente'].map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
const safeName=s=>String(s).replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').replace(/[. ]+$/,'').slice(0,130)||'Sin nombre';
async function chooseFolder(){if(!window.showDirectoryPicker){toast('Usa Chrome o Edge de escritorio para elegir una carpeta. También puedes descargar los documentos individualmente.');return;}folderHandle=await window.showDirectoryPicker({mode:'readwrite',id:'atlante-archivo'});toast('Carpeta seleccionada. Las próximas subidas guardarán también una copia local.');if(page==='settings')renderMain();}
async function writeLocal(path,blob){if(!folderHandle)return;let dir=await folderHandle.getDirectoryHandle('Ayudas, licitaciones y subvenciones',{create:true});const parts=path.split('/').map(safeName);for(const p of parts.slice(0,-1))dir=await dir.getDirectoryHandle(p,{create:true});const file=await dir.getFileHandle(parts.at(-1),{create:true});const stream=await file.createWritable();await stream.write(blob);await stream.close();}
async function mirrorDocument(d){const r=await fetch('/api/documents/'+encodeURIComponent(d.id));if(!r.ok)throw Error('No se pudo descargar '+d.name);const blob=await r.blob();await writeLocal(d.key,blob);if(libraryDocument(d))await writeLocal('Documentos del cliente/'+safeName(client(d.client_id).profile.name)+'/'+safeName(d.type)+(d.year?' '+d.year:'')+'/'+d.id+'_'+d.name,blob);}
async function syncFolder(){if(!folderHandle){await chooseFolder();if(!folderHandle)return;}toast('Copiando archivo a tu carpeta local…');for(const d of S.documents)await mirrorDocument(d);for(const c of S.cases){const o=op(c.opId),p=client(c.clientId);for(const r of c.requirements.filter(r=>r.reused&&r.docId)){const d=doc(r.docId);if(!d)continue;const response=await fetch('/api/documents/'+encodeURIComponent(d.id));if(!response.ok)throw Error('No se pudo copiar '+d.name);await writeLocal((o.type==='Licitación'?'Licitaciones':o.type==='Subvención'?'Subvenciones':'Ayudas')+'/'+safeName(p.profile.name)+'/'+safeName(o.title)+' '+c.created.slice(0,7)+'/'+safeName(r.type)+'_'+d.name,await response.blob());}}toast('Archivo copiado: '+S.documents.length+' documentos y vínculos reutilizados.');}
async function uploadFile(form){toast('Guardando documento…');const saved=await api('documents',form);await refresh();let problem=false;if(folderHandle){try{await mirrorDocument(doc(saved.id));}catch(e){problem=true;toast('Guardado en Atlante; la copia local falló: '+e.message);}}if(!problem)toast('Documento guardado y asociado'+(folderHandle?' · copia local creada.':'.'));renderMain();const id=form.get('caseId');if(id)caseDetail(id);else closeModal();}
async function busy(el,fn){if(el?.dataset.busy)return;try{if(el){el.dataset.busy='1';el.disabled=true;}await fn();}catch(e){toast(e.message||String(e));}finally{if(el){el.disabled=false;delete el.dataset.busy;}}}
async function start(){try{await refresh();render();if(S.settings.agencyName&&S.currentUser&&!S.currentUser.welcomed)welcomeTeam();}catch(e){if(e.signIn){renderWelcome();return;}root.innerHTML='<main class="main">'+head('Tu espacio no ha podido cargarse.','Revisa la conexión y vuelve a intentarlo.')+'<div class="error-box">'+esc(e.message)+'</div><button class="btn primary" onclick="location.reload()">Volver a cargar</button></main>';}}

document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action;
 const simple={'new-source':sourceDialog,identity:()=>{go('settings');document.getElementById('personal-form')?.scrollIntoView({block:'start'});document.getElementById('personal-name')?.focus({preventScroll:true});},'client-tab':()=>{clientTab=el.dataset.tab;renderMain();},'client-files':()=>{selectedClient=el.dataset.id;clientTab='archive';renderMain();},'client-file-upload':()=>uploadDialog(el.dataset.id),'calendar-view':()=>{calendarView=el.dataset.view;renderMain();},'calendar-move':()=>{moveCalendar(Number(el.dataset.step));},'calendar-today':()=>{calendarAnchor=todayCanary();renderMain();},nav:()=>go(el.dataset.page),'select-op-selection':()=>{bulkSelect=true;selectedOpIds.clear();renderMain();},'cancel-op-selection':()=>{bulkSelect=false;selectedOpIds.clear();renderMain();},'select-all-ops':()=>{unclassifiedOps().filter(o=>normalize(o.title).includes(normalize(q))).forEach(o=>selectedOpIds.add(o.id));renderMain();},menu:()=>document.querySelector('.sidebar').classList.toggle('open'),close:closeModal,'new-client':()=>editor(),'client':()=>openClient(el.dataset.id),'edit-client':()=>editor(client(el.dataset.id)),group:()=>{groupIndex=Number(el.dataset.index);renderEditor();},op:()=>opDetail(el.dataset.id),'new-op':()=>opEditor(),'edit-op':()=>opEditor(el.dataset.id),case:()=>caseDetail(el.dataset.id),'case-tab':()=>caseDetail(currentCase.id,el.dataset.tab),'new-case':()=>newCaseDialog(),'client-cases':()=>openClient(el.dataset.id),'client-new-case':()=>newCaseDialog(el.dataset.id),import:importDialog,template:downloadTemplate,dictionary,advanced:advancedDialog,'add-filter':()=>{advanced.push({field:'employees',op:'gte',value:''});drawFilters();},'remove-filter':()=>{advanced.splice(Number(el.dataset.index),1);drawFilters();},'clear-filters':()=>{advanced=[];drawFilters();},'apply-filters':()=>{closeModal();renderMain();},'add-rule':()=>{opEditing.rules.push({field:'employees',op:'lte',value:''});drawRules();},'remove-rule':()=>{opEditing.rules.splice(Number(el.dataset.index),1);drawRules();},'vault-upload':()=>uploadDialog(),'review-doc':()=>docReview(el.dataset.id),'upload-req':()=>{const r=currentCase.requirements.find(r=>r.id===el.dataset.id);uploadDialog(currentCase.clientId,currentCase.id,r.id,r.type);}};
 if(simple[a]){simple[a]();return;}
 await busy(el,async()=>{
 if(a==='ignore-one'||a==='ignore-selected'){
  const ids=a==='ignore-one'?[el.dataset.id]:[...selectedOpIds].filter(id=>unclassifiedOps().some(o=>o.id===id&&normalize(o.title).includes(normalize(q))));
  if(!ids.length)throw Error('Selecciona al menos una convocatoria');
  const names=ids.map(id=>op(id)?.title).filter(Boolean);
  showModal('Marcar No interesa','<p>Se retirarán '+ids.length+' convocatoria(s) de Pendientes de clasificar y de los posibles encajes de esta asesoría.</p><p class="help">Podrás restaurarlas aquí. Una nueva versión volverá a revisión.</p><div class="ignore-preview">'+names.slice(0,6).map(n=>'<div>· '+esc(n)+'</div>').join('')+(names.length>6?'<p>Y '+(names.length-6)+' más.</p>':'')+'</div>',button('Cancelar','close')+button('Confirmar No interesa','confirm-ignore','close',true,'data-ids="'+attr(ids.join(','))+'"'));
 }
 else if(a==='confirm-ignore'){const ids=String(el.dataset.ids||'').split(',').filter(Boolean);await api('opportunities/ignore',{ids,ignored:true});selectedOpIds.clear();bulkSelect=false;await refresh();closeModal();renderMain();toast(ids.length+' convocatoria(s) marcadas No interesa.');}
 else if(a==='restore-op'){await api('opportunities/ignore',{ids:[el.dataset.id],ignored:false});await refresh();renderMain();toast('Convocatoria restaurada.');}
 else if(a==='enter-workspace'){if(S.currentUser)await api('account/welcome',{});await refresh();closeModal();render();}
 else if(a==='reuse-docs'){const r=await api('cases/reuse',{id:currentCase.id});await refresh();caseDetail(currentCase.id);if(folderHandle)await mirrorCase(S.cases.find(x=>x.id===currentCase.id));toast(r.count+' documentos vinculados del archivo.');}
 else if(a==='dismiss-match'){showModal('Retirar de encaje','<form id="dismiss-form"><input type="hidden" name="clientId" value="'+attr(el.dataset.client)+'"><input type="hidden" name="opId" value="'+attr(el.dataset.op)+'"><div class="field"><label>Motivo</label><select name="category"><option>No le interesa</option><option>No cumple un requisito</option></select></div><div class="field"><label>Detalle del motivo</label><textarea name="reason" required maxlength="1400" aria-label="Detalle del motivo"></textarea></div><p class="help">Se retira solo para este cliente. Puedes restaurarla desde Encaje.</p><button class="btn primary" type="submit">Guardar retirada</button></form>');}
 else if(a==='restore-match'){await api('decisions',{clientId:el.dataset.client,opId:el.dataset.op,status:'active',reason:''});await refresh();renderMain();}
 else if(a==='initialize'){await api('initialize',{});await refresh();render();toast('Ejemplo cargado. Puedes editar las fichas y probar los expedientes.');}
 else if(a==='scan'){toast('Consultando las cinco fuentes. Puede tardar hasta dos minutos…');await api('scan',{});await refresh();render();toast('Consulta finalizada. Revisa la cobertura e incidencias en Fuentes oficiales.');}
 else if(a==='save-client'){const c=await api('clients',clientEdit);await refresh();closeModal();renderMain();toast('Ficha guardada: '+c.profile.name);}
 else if(a==='confirm-import'){const result=await api('clients/import',{clients:imported});await refresh();closeModal();renderMain();toast(result.count+' clientes importados.');}
 else if(a==='open-case')await openApplication(el.dataset.client,el.dataset.op);
 else if(a==='save-notes')await updateCase({notes:document.getElementById('case-notes').value});
 else if(a==='add-req'){const type=prompt('Nombre exacto del documento requerido:');if(type?.trim())await updateCase({requirements:[...currentCase.requirements,{id:crypto.randomUUID(),type:type.trim(),docId:null,reused:false}]});}
 else if(a==='sync-req'){const o=op(currentCase.opId);const missing=o.requirements.filter(t=>!currentCase.requirements.some(r=>normalize(r.type)===normalize(t)));if(!missing.length){toast('La lista ya incluye los documentos registrados.');return;}await updateCase({requirements:[...currentCase.requirements,...missing.map(type=>({id:crypto.randomUUID(),type,docId:null,reused:false}))]});}
 else if(a==='save-mail'){await updateCase({mail:mailValues()});toast('Borrador guardado en el expediente.');}
 else if(a==='gmail'){const m=mailValues();if(!m.to||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m.to))throw Error('Introduce un destinatario válido.');if(['Comunicado','Descartado','No cumple'].includes(currentCase.communication))throw Error('La comunicación está bloqueada.');window.open(gmailUrl(m),'_blank','noopener,noreferrer');await updateCase({mail:m,communication:'Abierto en Gmail'});toast('Se ha solicitado abrir Gmail con el mensaje. Revísalo allí antes de enviarlo.');}
 else if(a==='folder')await chooseFolder();
 else if(a==='sync-folder')await syncFolder();
 else if(a==='backup'){download('Atlante-datos-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(await api('backup'),null,2),'application/json');}
 });
});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.profile)clientEdit.profile[t.dataset.profile]=t.value;if(t.dataset.afValue!==undefined)advanced[Number(t.dataset.afValue)].value=t.value;if(t.dataset.ruleValue!==undefined){const r=opEditing.rules[Number(t.dataset.ruleValue)];r.value=r.op==='in'?t.value.split('|').map(s=>s.trim()):t.value;}});
let searchTimer;
document.addEventListener('input',e=>{if(!e.target.matches('[data-search],#global-search'))return;const t=e.target;clearTimeout(searchTimer);const value=t.value,pos=t.selectionStart;searchTimer=setTimeout(()=>{if(t.id==='global-search'){page='clients';location.hash=page;}if(page==='unclassified')selectedOpIds.clear();q=value;renderMain();const input=document.querySelector('[data-search]');if(t.id!=='global-search'){input?.focus();input?.setSelectionRange(pos,pos);}},180);});
document.addEventListener('change',async e=>{
 const t=e.target;if(t.dataset.opSelect){if(t.checked)selectedOpIds.add(t.dataset.opSelect);else selectedOpIds.delete(t.dataset.opSelect);renderMain();return;}if(t.dataset.filter){filters[t.dataset.filter]=t.value;renderMain();}
 if(t.dataset.afField!==undefined)advanced[Number(t.dataset.afField)].field=t.value;
 if(t.dataset.afOp!==undefined){advanced[Number(t.dataset.afOp)].op=t.value;drawFilters();}
 if(t.dataset.ruleField!==undefined)opEditing.rules[Number(t.dataset.ruleField)].field=t.value;
 if(t.dataset.ruleOp!==undefined){const r=opEditing.rules[Number(t.dataset.ruleOp)];r.op=t.value;if(r.op==='in'&&!Array.isArray(r.value))r.value=String(r.value).split('|');if(r.op!=='in'&&Array.isArray(r.value))r.value=r.value.join('|');drawRules();}
 if(t.id==='case-status')await busy(t,()=>updateCase({status:t.value}));
 if(t.id==='communication-status')await busy(t,async()=>{let reason='';if(['No cumple','Descartado'].includes(t.value))reason=prompt('Motivo (se guardará en el expediente):')||'';await updateCase({communication:t.value,dismissReason:reason},'mail');});
 if(t.id==='csv-file')await busy(null,async()=>{document.querySelector('[data-action="confirm-import"]').disabled=true;const file=t.files?.[0];if(!file)return;if(file.size>3_000_000)throw Error('El CSV supera 3 MB.');imported=parseCSV(await file.text());if(imported.length>500)throw Error('Máximo 500 clientes por archivo.');imported.forEach(c=>validateProfile(c.profile));document.getElementById('import-preview').innerHTML='<div class="note" style="margin-top:17px">'+ic('check')+imported.length+' clientes leídos. Revisa antes de importar.</div><div class="import-preview tablewrap"><table><thead><tr><th>Cliente</th><th>Correo</th><th>Variables</th></tr></thead><tbody>'+imported.slice(0,20).map(c=>'<tr><td>'+esc(c.profile.name)+'</td><td>'+esc(c.profile.email||'Pendiente')+'</td><td>'+Object.keys(c.profile).length+'</td></tr>').join('')+'</tbody></table></div>';document.querySelector('[data-action="confirm-import"]').disabled=false;});
});
document.addEventListener('submit',e=>{
 const form=e.target;if(!['personal-form','source-form','identity-form','dismiss-form','client-form','settings-form','new-case-form','upload-form','doc-review-form','op-form'].includes(form.id))return;e.preventDefault();
 busy(form.querySelector('[type=submit],button:not([type=button])'),async()=>{
 const f=new FormData(form),v=Object.fromEntries(f);
 if(form.id==='personal-form'){await api('account',v);await refresh();render();toast('Tu perfil personal está guardado.');}
 else if(form.id==='source-form'){await api('sources',v);await refresh();closeModal();renderMain();toast('Fuente guardada para consulta manual.');}
 else if(form.id==='dismiss-form'){await api('decisions',{clientId:v.clientId,opId:v.opId,status:'dismissed',reason:v.category+': '+v.reason});await refresh();closeModal();renderMain();toast('Retirada guardada para este cliente.');}
 else if(form.id==='identity-form'){await api('settings/identity',v);await refresh();render();toast('Datos de la asesoría guardados.');}
 else if(form.id==='settings-form'){await api('settings',v);await refresh();renderMain();toast('Preferencias guardadas. El horario de ejecución se aplica desde el chat.');}
 else if(form.id==='new-case-form')await openApplication(v.clientId,v.opId);
 else if(form.id==='upload-form'){if(f.get('fixedClient'))f.set('clientId',f.get('fixedClient'));await uploadFile(f);}
 else if(form.id==='doc-review-form'){await api('documents/review',{id:v.id,approved:f.has('approved'),expires:v.expires,scope:v.scope,year:v.year});await refresh();if(folderHandle){try{await mirrorDocument(doc(v.id));}catch(e){toast('Revisión guardada; copia local pendiente: '+e.message);}}closeModal();renderMain();toast('Revisión guardada.');}
 else if(form.id==='op-form'){const sources=String(v.sources||'').split('\n').filter(x=>x.trim()).map(line=>{const [name,url,...rest]=line.split('|').map(s=>s.trim());return {name,url,section:rest.join('|')};});const data={...opEditing,...v,verified:f.has('verified'),sources,requirements:String(v.requirements||'').split('\n').map(x=>x.trim()).filter(Boolean),rules:opEditing.rules.map(r=>({...r,label:FIELDS.find(f=>f.key===r.field)?.label})),sector:opEditing.sector||'Todos',tag:opEditing.tag||'Revisión'};const saved=await api('opportunities',data);await refresh();renderMain();opDetail(saved.id);toast('Análisis guardado con su versión y fuentes.');}
 });
});
document.addEventListener('dragover',e=>{const el=e.target.closest('[data-drop]');if(el){e.preventDefault();el.classList.add('dragover');}});
document.addEventListener('dragleave',e=>e.target.closest('[data-drop]')?.classList.remove('dragover'));
document.addEventListener('drop',e=>{const el=e.target.closest('[data-drop]');if(!el)return;e.preventDefault();el.classList.remove('dragover');const file=e.dataTransfer.files[0];if(!file)return;const r=currentCase.requirements.find(r=>r.id===el.dataset.drop),f=new FormData();f.set('file',file);f.set('clientId',currentCase.clientId);f.set('caseId',currentCase.id);f.set('reqId',r.id);f.set('type',r.type);busy(null,()=>uploadFile(f));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('.sidebar')?.classList.remove('open');}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-search')?.focus();}if(e.key==='Tab'&&document.getElementById('modal')){const f=[...document.getElementById('modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea,a[href]')].filter(x=>x.offsetParent!==null);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'overview';if(p!==page){selectedClient=null;page=['cases','documents'].includes(p)?'clients':p;render();}});
function clientCases(id){const c=client(id);showModal('Expedientes de '+esc(c.profile.name),caseTable(S.cases.filter(x=>x.clientId===id)),button('Abrir nuevo expediente','client-new-case','plus',true,'data-id="'+attr(id)+'"'),'wide');}

let selectedClient=null,clientTab='requested',calendarView='month',calendarAnchor=todayCanary();
function decision(clientId,opId){return (S.decisions||[]).find(d=>d.clientId===clientId&&d.opId===opId);}
function ignoredRecord(o){return (S.ignored||[]).find(x=>x.opId===o.id);}
function isIgnored(o){const r=ignoredRecord(o);return r?.status==='ignored'&&r.version===o.version;}
function unclassifiedOps(){const active=S.clients.filter(c=>c.profile.active!=='No');return S.opportunities.filter(o=>!o.demo&&!o.screenedOut&&!isIgnored(o)&&!matches(o).length&&active.some(c=>preliminary(c,o).status==='unknown'&&!isDismissed(c.id,o.id)));}
function unclassified(){
 const list=unclassifiedOps().filter(o=>normalize(o.title).includes(normalize(q)));
 const ignored=S.opportunities.filter(isIgnored);
 const selected=[...selectedOpIds].filter(id=>list.some(o=>o.id===id));
 const actions=list.length?button(bulkSelect?'Cancelar selección':'Seleccionar varios',bulkSelect?'cancel-op-selection':'select-op-selection','check'):'';
 const header=head('Pendientes de clasificar','Anuncios conservados porque falta información para valorar su encaje.',actions);
 const bar='<div class="toolbar"><input data-search placeholder="Buscar anuncios…" value="'+attr(q)+'"><span class="countpill">'+list.length+' '+(list.length===1?'anuncio':'anuncios')+'</span></div>';
 const bulk=bulkSelect?'<div class="panel bulk-actions"><span><strong>'+selected.length+'</strong> seleccionadas</span><div class="row wrap">'+button('Seleccionar todos los visibles','select-all-ops','check')+button('No interesa ('+selected.length+')','ignore-selected','close',true,selected.length?'':'disabled')+'</div></div>':'';
 const cards=list.length?'<div class="op-grid">'+list.map(o=>'<div class="pending-op">'+(bulkSelect?'<label class="op-select"><input type="checkbox" data-op-select="'+attr(o.id)+'" '+(selectedOpIds.has(o.id)?'checked':'')+'><span>Seleccionar convocatoria</span></label>':'')+opCard(o)+(bulkSelect?'':'<div class="pending-op-actions">'+button('No interesa','ignore-one','close',false,'data-id="'+attr(o.id)+'"')+'</div>')+'</div>').join('')+'</div>':empty('Sin anuncios pendientes','Los nuevos anuncios sin criterios suficientes aparecerán aquí.');
 const archived=ignored.length?'<details class="panel ignored-list"><summary>No interesan · '+ignored.length+'</summary><p class="help">Estas convocatorias permanecen archivadas en tu asesoría. Una versión nueva volverá a revisión.</p>'+ignored.map(o=>'<div class="row between wrap ignored-row"><span>'+esc(o.title)+'</span>'+button('Restaurar','restore-op','refresh',false,'data-id="'+attr(o.id)+'"')+'</div>').join('')+'</details>':'';
 return header+bar+bulk+cards+archived;
}
function openClient(id){selectedClient=id;clientTab='requested';page='clients';location.hash='clients';q='';closeModal();render();}
function clientWorkspace(){const c=client(selectedClient);if(!c){selectedClient=null;return clients();}const requests=S.cases.filter(x=>x.clientId===c.id&&isRequested(x,decision(c.id,x.opId))),potentials=S.opportunities.filter(o=>!isIgnored(o)&&preliminary(c,o).status==='potential'&&!S.cases.some(x=>x.clientId===c.id&&x.opId===o.id&&isRequested(x,decision(c.id,o.id)))&&!isDismissed(c.id,o.id)),dismissed=(S.decisions||[]).filter(d=>d.clientId===c.id&&d.status==='dismissed');return head(esc(c.profile.name),'',button('Volver a clientes','nav','',false,'data-page="clients"')+button('Ficha','edit-client','edit',false,'data-id="'+attr(c.id)+'"')+button('Archivo del cliente','client-files','folder',false,'data-id="'+attr(c.id)+'"'))+'<div class="tabs">'+[['requested','Solicitadas',requests.length],['potential','Encaje',potentials.length],['archive','Documentos del cliente',S.documents.filter(d=>d.client_id===c.id&&libraryDocument(d)).length]].map(([t,l,n])=>'<button class="'+(clientTab===t?'active':'')+'" data-action="client-tab" data-tab="'+t+'">'+l+' · '+n+'</button>').join('')+'</div>'+(clientTab==='archive'?clientArchive(c.id):clientTab==='requested'?'<p class="help">Ayudas que el cliente ha decidido tramitar. El estado indica si están en preparación o ya presentadas.</p>'+caseTable(requests):'<p class="help">Explora las coincidencias preliminares. Consulta las bases antes de decidir.</p>'+potentials.map(o=>'<div class="panel"><h3>'+esc(o.title)+'</h3><p class="help">'+esc(preliminary(c,o).reasons.join('; '))+'</p><div class="row wrap">'+button('Ver convocatoria','op','link',false,'data-id="'+attr(o.id)+'"')+button('El cliente quiere solicitarla','open-case','plus',true,'data-client="'+attr(c.id)+'" data-op="'+attr(o.id)+'"')+button('Retirar de encaje','dismiss-match','close',false,'data-client="'+attr(c.id)+'" data-op="'+attr(o.id)+'"')+'</div></div>').join('')+(!potentials.length?empty('Sin nuevas coincidencias','Las oportunidades se revisan con los datos actuales del cliente.'):'')+(dismissed.length?'<details class="panel"><summary>Retiradas · '+dismissed.length+'</summary>'+dismissed.map(d=>'<div class="row between" style="margin-top:14px"><div>'+esc(op(d.opId)?.title)+'<p class="help">'+esc(d.reason)+'</p></div>'+button('Restaurar','restore-match','refresh',false,'data-client="'+attr(c.id)+'" data-op="'+attr(d.opId)+'"')+'</div>').join('')+'</details>':''));}
function clientFiles(id){const list=S.documents.filter(d=>d.client_id===id);showModal('Archivo de '+esc(client(id).profile.name),list.length?'<div class="stack">'+list.map(d=>'<div class="document-row"><div class="docinfo"><strong>'+esc(d.type)+'</strong><p>'+esc(d.name)+' · '+fullDate(d.created)+' · '+esc(d.actor)+'</p>'+badge(d.approved?'Apto para reutilizar':'Pendiente de revisión')+'</div><a class="btn" href="/api/documents/'+encodeURIComponent(d.id)+'">Descargar</a>'+button('Revisar','review-doc','check',false,'data-id="'+attr(d.id)+'"')+'</div>').join('')+'</div>':empty('Sin documentos','Sube documentos permanentes o añádelos a una solicitud.'),button('Subir documento','client-file-upload','up',true,'data-id="'+attr(id)+'"')+button('Carpeta local','folder','folder'),'wide');}
function moveCalendar(step){const d=new Date(calendarAnchor+'T12:00:00Z');if(calendarView==='month'){d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+step);}else d.setUTCDate(d.getUTCDate()+step*(calendarView==='week'?7:14));calendarAnchor=d.toISOString().slice(0,10);renderMain();}

function isDismissed(clientId,opId){return decision(clientId,opId)?.status==='dismissed'||S.cases.some(c=>c.clientId===clientId&&c.opId===opId&&['Descartado','No cumple'].includes(c.communication));}

function identityForm(){return '<form id="identity-form" class="panel settings-card"><h3>Datos de la asesoría</h3><p class="help">Información común del equipo. Los clientes se gestionan desde este espacio interno.</p><div class="formgrid"><div class="field"><label for="agency-name">Nombre de la asesoría</label><input id="agency-name" name="agencyName" maxlength="120" required value="'+attr(S.settings.agencyName||'Mi asesoría')+'"></div><div class="field"><label for="contact-email">Correo de contacto de la asesoría</label><input id="contact-email" name="contactEmail" type="email" maxlength="254" value="'+attr(S.settings.contactEmail||'')+'"></div></div><button class="btn primary" type="submit">Guardar datos de la asesoría</button></form>';}


function sourceDialog(){showModal('Añadir fuente','<form id="source-form"><div class="field"><label for="source-name">Nombre</label><input id="source-name" name="name" required maxlength="120"></div><div class="field"><label for="source-url">Enlace oficial HTTPS</label><input id="source-url" name="url" type="url" required placeholder="https://…"></div><div class="field"><label for="source-notes">Ámbito o notas</label><textarea id="source-notes" name="notes" maxlength="1000"></textarea></div><p class="help">Se guarda como fuente de consulta manual. Cada portal necesita un lector específico para incorporar automáticamente sus anuncios.</p><button class="btn primary" type="submit">Guardar fuente</button></form>','','small');}
function clientArchive(id){const docs=S.documents.filter(d=>d.client_id===id),general=docs.filter(libraryDocument),specific=docs.filter(d=>!libraryDocument(d));const rows=list=>list.map(d=>'<div class="document-row"><div class="docinfo"><strong>'+esc(d.type)+(d.year?' · '+esc(d.year):'')+'</strong><p>'+esc(d.name)+' · Subido '+fullDate(d.created)+' · '+esc(d.actor)+'</p>'+badge(d.expires&&d.expires<todayCanary()?'Caducado':d.approved?'Revisado para reutilizar':'Pendiente de revisión','gray')+(d.expires?'<p>Caduca: '+shortDate(d.expires)+'</p>':'')+'<p class="help">'+(d.case_id?'Procede de: '+esc(op(S.cases.find(c=>c.id===d.case_id)?.opId)?.title||'Trámite'):'Subido al archivo del cliente')+'</p></div><a class="btn" href="/api/documents/'+encodeURIComponent(d.id)+'">Descargar</a>'+button('Clasificar y revisar','review-doc','check',false,'data-id="'+attr(d.id)+'"')+'</div>').join('');return '<p class="help">Escrituras, cuentas y certificados del cliente. Un documento subido en un trámite puede incorporarse aquí al clasificarlo como documento del cliente. El archivo se guarda una sola vez en Atlante.</p><div class="row wrap" style="margin-bottom:20px">'+button('Subir documento','client-file-upload','up',true,'data-id="'+attr(id)+'"')+button('Elegir carpeta local','folder','folder')+button('Sincronizar copias locales','sync-folder','down')+'</div>'+rows(general)+(!general.length?empty('Sin documentos generales','Sube un documento o clasifica uno de los trámites.'):'')+'<p class="help">Se reutilizan los documentos revisados, no caducados y del mismo tipo. En cuentas anuales debe coincidir también el ejercicio indicado en el requisito. La reutilización no acredita que la administración vaya a aceptarlos.</p>'+(specific.length?'<details class="panel"><summary>Documentos de trámites · '+specific.length+'</summary>'+rows(specific)+'</details>':'');}
async function mirrorCase(c){const o=op(c.opId),p=client(c.clientId);for(const r of c.requirements.filter(r=>r.reused&&r.docId)){const d=doc(r.docId);if(!d)continue;const res=await fetch('/api/documents/'+encodeURIComponent(d.id));if(!res.ok)throw Error('No se pudo descargar '+d.name);await writeLocal((o.type==='Licitación'?'Licitaciones':o.type==='Subvención'?'Subvenciones':'Ayudas')+'/'+safeName(p.profile.name)+'/'+safeName(o.title)+' '+c.created.slice(0,7)+'/'+safeName(r.type)+'_'+d.name,await res.blob());}}

function advisorIntro(){return '<section class="advisor-intro"><div><span class="eyebrow">PARA EQUIPOS DE ASESORÍA</span><h2>Una gestión coordinada, de la oportunidad al expediente.</h2><p>Tu equipo detecta oportunidades, reúne la documentación de sus clientes y lleva el seguimiento de cada solicitud.</p><p class="help">Acceso interno del equipo. Los clientes son las empresas y personas a las que prestáis el servicio; no acceden a este espacio.</p></div><div class="advisor-steps"><div>'+ic('users')+'Clientes de la asesoría</div><div>'+ic('folder')+'Documentos y solicitudes</div><div>'+ic('clock')+'Quién hizo qué y cuándo</div></div></section>';}
function welcomeTeam(){showModal('Atlante · Para equipos de asesoría',advisorIntro()+'<p>Has accedido como <strong>'+esc(S.currentUser.name)+'</strong> · '+esc(S.currentUser.email)+'. Tus próximas acciones quedarán asociadas a esta cuenta.</p><p class="help">Cada compañera debe entrar con su propia cuenta autorizada. No compartáis una misma sesión si necesitáis distinguir quién realizó una acción.</p>',button('Entrar al espacio de la asesoría','enter-workspace','arrow',true),'wide');}
function personalForm(){const u=S.currentUser;if(!u)return '<div class="panel"><h3>Mi perfil</h3><p>Esta conexión no aporta una identidad personal.</p><a class="btn" href="/signin-with-chatgpt?return_to=%2F%23settings" target="_top">Iniciar sesión con mi cuenta</a></div>';return '<form id="personal-form" class="panel settings-card"><h3>Mi perfil personal</h3><p class="help">Cuenta autenticada: '+esc(u.email)+'. El correo y el identificador de cuenta se conservan en el seguimiento aunque cambies tu nombre.</p><div class="formgrid"><div class="field"><label for="personal-name">Tu nombre</label><input id="personal-name" name="name" required maxlength="160" value="'+attr(u.name)+'"></div><div class="field"><label for="personal-department">Departamento</label><input id="personal-department" name="department" maxlength="120" value="'+attr(u.department||'')+'"></div><div class="field wide"><label for="personal-signature">Tu firma para nuevos borradores</label><textarea id="personal-signature" name="signature" maxlength="2000">'+esc(u.signature||'')+'</textarea></div></div><div class="row wrap"><button type="submit" class="btn primary">Guardar mi perfil</button><a class="btn" href="/signout-with-chatgpt?return_to=%2F" target="_top">Cerrar sesión</a></div></form>';}
function teamPanel(){return '<section class="panel"><h3>Espacio independiente</h3><p>Los clientes, expedientes y documentos de esta asesoría están vinculados a tu cuenta. Otra persona que se registre creará su propia asesoría vacía.</p><p class="help">El acceso de varios empleados a una misma asesoría queda pendiente de incorporar. No se han enviado invitaciones.</p></section>';}
async function loadCaseHistory(id){try{const logs=await api('cases/history?id='+encodeURIComponent(id));if(currentCase?.id!==id||activeTab!=='timeline')return;S.logs=[...S.logs.filter(l=>l.caseId!==id),...logs];renderCaseTab();}catch(e){if(currentCase?.id===id&&activeTab==='timeline')document.getElementById('case-content').innerHTML='<p class="help">No se pudo cargar el seguimiento completo: '+esc(e.message)+'</p>';}}

function renderWelcome(){root.innerHTML='<main class="main access-page"><div class="brand">atlante</div><button class="btn" data-install-atlante>Instalar Atlante</button><p class="eyebrow">PARA ASESORÍAS</p><h1>Las ayudas de tus clientes,<br>bajo control.</h1><p>Organiza oportunidades, documentación y seguimiento en un espacio propio para tu asesoría.</p><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Crear mi asesoría</a> <a class="btn" href="/signin-with-chatgpt?return_to=%2F" target="_top">Iniciar sesión</a><p class="help">Accede con tu cuenta de ChatGPT. Cada cuenta dispone de su propio espacio privado. La consulta de fuentes es parcial y el análisis completo de bases requiere revisión.</p></main>';}
function renderRegistration(){root.innerHTML='<main class="main access-page"><div class="brand">atlante</div><h1>Crea el espacio de tu asesoría.</h1><p>Empieza con tu propia base de clientes. No se cargarán clientes ni documentos de otras asesorías.</p><form id="agency-registration" class="panel"><div class="field"><label for="agency-name">Nombre de la asesoría</label><input id="agency-name" name="name" required maxlength="120" autocomplete="organization"></div><p class="help">Cuenta: '+esc(S.currentUser?.email)+'</p><button class="btn primary">Crear mi asesoría</button></form><p>¿Quieres probar los filtros? <a href="/50-clientes-ficticios.csv" download>Descarga aquí 50 clientes ficticios en CSV</a> e impórtalos desde Clientes.</p><a href="/signout-with-chatgpt?return_to=%2F" target="_top">Usar otra cuenta</a></main>';document.getElementById('agency-registration').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('agency',{name:new FormData(e.target).get('name')});await refresh();render();}catch(error){toast(error.message);b.disabled=false;}});}
